example.code:
var response = await jsonRpcSender.InvokeMethodAsync(
    "version",
    new VersionParameters(),
    SignalJsonContext.Default.VersionParameters,
    SignalJsonContext.Default.VersionResponse,
    cancellationToken);

var accounts = await signalAccounts.ListAccounts(cancellationToken);
foreach (var account in accounts)
{
    Console.WriteLine($"Зареєстрований акаунт: {account.Number}");
}

// Крок 1: Початок процесу зв'язування
var linkInfo = await signalDevices.StartLink(cancellationToken);

// Виведення QR-коду для сканування на іншому пристрої
Console.WriteLine($"Відскануйте цей код: {linkInfo.DeviceLinkUri}");

// Крок 2: Завершення процесу після сканування
var result = await signalDevices.FinishLink(
    deviceLinkUri: "tsdevice:/?uuid=...",
    deviceName: "Мій новий пристрій",
    cancellationToken);

var groups = await signalGroups.ListGroups("+380501234567", cancellationToken);
foreach (var group in groups)
{
    Console.WriteLine($"Група: {group.Name}, Учасників: {group.Members.Count}");
}

var textOptions = new TextMessageOptions.Builder("+380501234567",
                         [new UserRecipient("+380501234567")],
                         "Привіт, світ!")
                         .UseStyle()
                         .Build();
var response = await signalMessage.SendTextMessageAsync(textOptions);

var attachmentOptions = new AttachmentMessageOptions.Builder("+380501234567",
                               [new UserRecipient("+380501234567")],
                               attachmentsList)
                               .WithMessage("Привіт, світ з вкладенням!")
                               .Build();
var response = await signalMessage.SendAttachmentAsync(attachmentOptions);

var stickerOptions = new StickerMessageOptions.Builder("+380501234567",
                         [new UserRecipient("+380501234567")],
                         "stickerPackId:stickerId")
                         .Build();
var response = await signalMessage.SendStickerAsync(stickerOptions);

remarks.para:
Зареєстровано у ServiceCollectionExtensions.AddSignalCli через
services.AddSingleton<IValidateOptions<SignalCliOptions>, SignalCliOptionsValidator>();
викликається автоматично при першому доступі до .

member.param:
Опціональний постачальник часу для таймера вікна стабільності рестартів
(). За замовчуванням ;
у тестах підставляється FakeTimeProvider, щоб обнулення лічильника не вимагало wall-clock.

member.remarks:
A.12: paramName автоматично береться з виразу-аргументу через
;
викликачу не треба явно передавати ім’я (рефакторинг безпечний).
